const timezone = 'N8N_TIMEZONE';

// Google returns cancelled instances of recurring events too; they are not commitments.
const events = $input
  .all()
  .map((item) => item.json)
  .filter((event) => event && event.status !== 'cancelled' && (event.start?.dateTime || event.start?.date));

const isAllDay = (event) => !event.start?.dateTime && Boolean(event.start?.date);

function formatInZone(date, options) {
  try {
    return new Intl.DateTimeFormat('en-GB', { timeZone: timezone, ...options }).format(date);
  } catch (error) {
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', ...options }).format(date);
  }
}

// en-CA gives YYYY-MM-DD, which sorts correctly as a plain string.
function dayKey(date) {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
  } catch (error) {
    return new Intl.DateTimeFormat('en-CA', { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
  }
}

// An all-day event carries a bare date; midday UTC keeps it on its own day in any zone.
const startDate = (event) => new Date(isAllDay(event) ? event.start.date + 'T12:00:00Z' : event.start.dateTime);

function bookedMinutes(event) {
  if (isAllDay(event)) return 0;
  const from = new Date(event.start.dateTime).getTime();
  const to = new Date(event.end?.dateTime ?? event.start.dateTime).getTime();
  return Math.max(0, Math.round((to - from) / 60000));
}

const byDay = new Map();
for (const event of events) {
  const key = dayKey(startDate(event));
  if (!byDay.has(key)) byDay.set(key, []);
  byDay.get(key).push(event);
}

const today = new Date();
const days = [];
for (let offset = 0; offset < 7; offset++) {
  days.push(dayKey(new Date(today.getTime() + offset * 86400000)));
}

const lines = [];
let totalMinutes = 0;
let busiestDay = null;

for (const key of days) {
  const dayEvents = (byDay.get(key) ?? []).sort((a, b) => startDate(a) - startDate(b));
  const label = formatInZone(new Date(key + 'T12:00:00Z'), { weekday: 'long', day: 'numeric', month: 'short' });
  const dayMinutes = dayEvents.reduce((sum, event) => sum + bookedMinutes(event), 0);
  totalMinutes += dayMinutes;

  if (dayEvents.length && (!busiestDay || dayMinutes > busiestDay.minutes)) {
    busiestDay = { label, minutes: dayMinutes, count: dayEvents.length };
  }

  if (dayEvents.length === 0) {
    lines.push(label + ': nothing scheduled');
    continue;
  }

  lines.push(label + ': ' + dayEvents.length + (dayEvents.length === 1 ? ' commitment' : ' commitments'));
  for (const event of dayEvents) {
    const title = event.summary ?? '(no title)';
    if (isAllDay(event)) {
      lines.push('  all day  ' + title);
      continue;
    }
    const from = formatInZone(new Date(event.start.dateTime), { hour: '2-digit', minute: '2-digit', hour12: false });
    const to = event.end?.dateTime
      ? formatInZone(new Date(event.end.dateTime), { hour: '2-digit', minute: '2-digit', hour12: false })
      : '';
    const where = event.location ? '  (' + event.location + ')' : '';
    lines.push('  ' + from + (to ? '-' + to : '') + '  ' + title + where);
  }
}

const hours = Math.round((totalMinutes / 60) * 10) / 10;
const freeDays = days.filter((key) => (byDay.get(key) ?? []).length === 0).length;

const headline = events.length === 0
  ? 'Nothing on the calendar for the next seven days.'
  : events.length + (events.length === 1 ? ' commitment' : ' commitments') + ' over the next seven days, ' + hours + 'h booked.';

const content = [
  headline,
  busiestDay ? 'Busiest: ' + busiestDay.label + ' (' + busiestDay.count + ', ' + Math.round(busiestDay.minutes / 6) / 10 + 'h).' : '',
  freeDays ? 'Clear days: ' + freeDays + '.' : '',
  '',
  lines.join('\n'),
].filter((part) => part !== '').join('\n');

const subject = events.length === 0
  ? 'Week ahead \u2014 nothing scheduled'
  : 'Week ahead \u2014 ' + events.length + (events.length === 1 ? ' commitment' : ' commitments') + ', ' + hours + 'h';

return [{ json: { subject, content } }];
